"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["53933"],{41863(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.ja_desativado","status":422,"titulo":"O fato j\xe1 est\xe1 desativado"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.ja_desativado","requisitos":["UNI-REQ-0143"],"oQueAconteceu":["O administrador pediu a desativa\xe7\xe3o de um fato do cat\xe1logo (`DELETE /api/configuracao/admin/fatos-candidato/{id}`), mas o fato j\xe1 est\xe1 desativado. O fato n\xe3o \xe9 apagado: a desativa\xe7\xe3o s\xf3 impede v\xednculos novos com ele e preserva os que j\xe1 existem (UNI-REQ-0143). Repetir o pedido n\xe3o tem efeito, e a API o recusa em vez de aceit\xe1-lo em sil\xeancio.","As confer\xeancias seguem esta ordem: o fato ([fato do candidato n\xe3o encontrado](/erros/uniplus.configuracao.fato_candidato.nao_encontrado)), a recusa de fato de sistema, que n\xe3o \xe9 desativado ([defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)) e, por \xfaltimo, o estado do fato. A resposta n\xe3o traz a lista `errors`. Nada \xe9 gravado."],"comoResolver":["N\xe3o h\xe1 nada a fazer: o fato j\xe1 n\xe3o aceita v\xednculos novos. Se o fato deve voltar a ser usado, reative-o (`POST /api/configuracao/admin/fatos-candidato/{id}/ativacao`)."],"ondeAparece":["Desativa\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);